'use client';

import * as React from 'react';
import { Pause, Play, Square } from 'lucide-react';
import { Slot } from 'radix-ui';

import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import {
  type CursorPlayerRuntime,
  useCursorPlayer,
} from './use-cursor-player';

interface CursorPlayerRootProps<TCursor extends CursorPlayerRuntime> {
  createCursor: (anchorElement: HTMLElement) => TCursor;
  buildSequence: (cursor: TCursor, anchorElement: HTMLElement) => void;
  onError?: (error: unknown) => void;
  children: React.ReactNode;
}

interface CursorPlayerPartProps extends React.HTMLAttributes<HTMLDivElement> {
  asChild?: boolean;
}

type CursorPlayerHotspot = 'top-left' | 'center' | { x: number; y: number };

interface CursorPlayerCursorProps extends CursorPlayerPartProps {
  hotspot?: CursorPlayerHotspot;
}

interface CursorPlayerButtonProps extends React.ComponentProps<typeof Button> {
  children?: React.ReactNode;
}

interface CursorPlayerIconProps extends React.HTMLAttributes<HTMLElement> {
  asChild?: boolean;
  children?: React.ReactNode;
}

const CursorPlayerContext = React.createContext<CursorPlayerContextValue | null>(null);

function useCursorPlayerContext() {
  const value = React.useContext(CursorPlayerContext);

  if (!value) {
    throw new Error('CursorPlayer components must be used inside <CursorPlayer>.');
  }

  return value;
}

function isPlayVisible(state: CursorPlayerContextValue['state']) {
  return state !== 'running';
}

function isPauseVisible(state: CursorPlayerContextValue['state']) {
  return state === 'running';
}

type CursorPlayerContextValue = ReturnType<typeof useCursorPlayer>;
type CursorPlayerRootComponent = <TCursor extends CursorPlayerRuntime>(
  props: CursorPlayerRootProps<TCursor>,
) => React.ReactElement;

const CursorPlayerRoot: CursorPlayerRootComponent = ({
  createCursor,
  buildSequence,
  onError,
  children,
}) => {
  const controls = useCursorPlayer({ createCursor, buildSequence, onError });

  return <CursorPlayerContext.Provider value={controls}>{children}</CursorPlayerContext.Provider>;
};

function getHotspotPosition(hotspot: CursorPlayerHotspot | undefined): { left: string; top: string } {
  if (hotspot === 'center') {
    return { left: '50%', top: '50%' };
  }

  if (hotspot && typeof hotspot === 'object') {
    return { left: `${hotspot.x}px`, top: `${hotspot.y}px` };
  }

  return { left: '0px', top: '0px' };
}

function CursorPlayerCursor({
  className,
  asChild = false,
  children,
  hotspot = 'top-left',
  ...props
}: CursorPlayerCursorProps) {
  const { setAnchorElement, setAnchorFrameElement } = useCursorPlayerContext();
  const Comp = asChild ? Slot.Root : 'span';
  const hotspotPosition = getHotspotPosition(hotspot);

  return (
    <Comp
      ref={setAnchorFrameElement}
      className={cn('relative inline-flex size-4 shrink-0 self-start justify-self-start', className)}
      aria-hidden="true"
      {...props}
    >
      <span
        ref={setAnchorElement}
        className="absolute h-px w-px"
        style={{
          left: hotspotPosition.left,
          top: hotspotPosition.top,
          transform: hotspot === 'center' ? 'translate(-50%, -50%)' : undefined,
        }}
      />
      {children}
    </Comp>
  );
}

function CursorPlayerPlayPause({
  className,
  asChild = false,
  onClick,
  ...props
}: CursorPlayerButtonProps) {
  const { state, start, pause } = useCursorPlayerContext();

  return (
    <Button
      type="button"
      variant="outline"
      className={className}
      asChild={asChild}
      onClick={(event) => {
        onClick?.(event);

        if (event.defaultPrevented) {
          return;
        }

        if (state === 'running') {
          pause();
          return;
        }

        void start();
      }}
      {...props}
    >
      {props.children}
    </Button>
  );
}

function CursorPlayerPlayIcon({
  className,
  children,
  asChild = false,
  ...props
}: CursorPlayerIconProps) {
  const { state } = useCursorPlayerContext();
  const Comp = asChild ? Slot.Root : 'span';

  if (!isPlayVisible(state)) {
    return null;
  }

  const content = children ?? <Play className="size-4" />;

  return (
    <Comp className={cn('pointer-events-none inline-flex items-center justify-center', className)} aria-hidden="true" {...props}>
      {content}
    </Comp>
  );
}

function CursorPlayerPauseIcon({
  className,
  children,
  asChild = false,
  ...props
}: CursorPlayerIconProps) {
  const { state } = useCursorPlayerContext();
  const Comp = asChild ? Slot.Root : 'span';

  if (!isPauseVisible(state)) {
    return null;
  }

  const content = children ?? <Pause className="size-4" />;

  return (
    <Comp className={cn('pointer-events-none inline-flex items-center justify-center', className)} aria-hidden="true" {...props}>
      {content}
    </Comp>
  );
}

function CursorPlayerStopButton({
  className,
  children,
  asChild = false,
  ...props
}: CursorPlayerButtonProps) {
  const { stop, canStop } = useCursorPlayerContext();
  const content = children ?? (
    <>
      <Square className="size-4" />
      Stop
    </>
  );

  return (
    <Button
      type="button"
      variant="ghost"
      className={className}
      asChild={asChild}
      onClick={stop}
      disabled={!canStop}
      {...props}
    >
      {content}
    </Button>
  );
}

export const CursorPlayer = Object.assign(CursorPlayerRoot, {
  Cursor: CursorPlayerCursor,
  PlayPause: CursorPlayerPlayPause,
  PlayIcon: CursorPlayerPlayIcon,
  PauseIcon: CursorPlayerPauseIcon,
  StopButton: CursorPlayerStopButton,
});

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export type CursorPlayerState = "idle" | "running" | "paused" | "complete" | "error";

export interface CursorPlayerRuntime extends PromiseLike<void> {
  cursor: {
    el: HTMLElement;
    scale: number;
    setSize: (scale: number) => void;
  };
  on(event: string, callback: () => void): this;
  off(event: string, callback: () => void): this;
  pause(): this;
  play(): this;
  destroy(): void;
}

export type CursorPlayerInstance = CursorPlayerRuntime;

export interface UseCursorPlayerOptions<TCursor extends CursorPlayerRuntime> {
  createCursor: (anchorElement: HTMLElement) => TCursor;
  buildSequence: (cursor: TCursor, anchorElement: HTMLElement) => void;
  onError?: (error: unknown) => void;
}

export interface CursorPlayerControls {
  state: CursorPlayerState;
  canStart: boolean;
  canPause: boolean;
  canStop: boolean;
  start: () => Promise<void>;
  pause: () => void;
  stop: () => void;
  setAnchorElement: (element: HTMLElement | null) => void;
  setAnchorFrameElement: (element: HTMLElement | null) => void;
}

interface CursorBinding<TCursor extends CursorPlayerRuntime> {
  cursor: TCursor;
  anchorElement: HTMLElement;
  anchorFrameElement: HTMLElement;
  activeScale: number;
  onPause: () => void;
  onPlay: () => void;
  onDestroy: () => void;
}

function resolveVisualElement(cursorElement: HTMLElement) {
  return (cursorElement.querySelector(".cursor-theme-wrapper") as HTMLElement | null) ?? cursorElement;
}

function syncCursorScale(cursor: CursorPlayerRuntime, anchorFrameElement: HTMLElement) {
  const anchorRect = anchorFrameElement.getBoundingClientRect();
  const visualElement = resolveVisualElement(cursor.cursor.el);
  const visualRect = visualElement.getBoundingClientRect();

  if (
    anchorRect.width <= 0 ||
    anchorRect.height <= 0 ||
    visualRect.width <= 0 ||
    visualRect.height <= 0
  ) {
    return;
  }

  const scale = Math.min(anchorRect.width / visualRect.width, anchorRect.height / visualRect.height);
  cursor.cursor.setSize(scale);
}

function restoreCursorScale(cursor: CursorPlayerRuntime, scale: number) {
  cursor.cursor.setSize(scale);
}

function isSameBinding<TCursor extends CursorPlayerRuntime>(
  currentBinding: CursorBinding<TCursor> | null,
  binding: CursorBinding<TCursor>,
) {
  return currentBinding?.cursor === binding.cursor;
}

export function useCursorPlayer<TCursor extends CursorPlayerRuntime>({
  createCursor,
  buildSequence,
  onError,
}: UseCursorPlayerOptions<TCursor>): CursorPlayerControls {
  const [state, setState] = useState<CursorPlayerState>("idle");
  const anchorElementRef = useRef<HTMLElement | null>(null);
  const anchorFrameElementRef = useRef<HTMLElement | null>(null);
  const bindingRef = useRef<CursorBinding<TCursor> | null>(null);
  const runIdRef = useRef(0);
  const resizeObserverRef = useRef<ResizeObserver | null>(null);

  const clearBinding = (destroyCursor: boolean) => {
    const binding = bindingRef.current;
    if (!binding) return;

    binding.cursor.off("pause", binding.onPause);
    binding.cursor.off("play", binding.onPlay);
    binding.cursor.off("destroy", binding.onDestroy);

    if (destroyCursor) {
      binding.cursor.destroy();
    }

    bindingRef.current = null;
  };

  const cleanupResizeObserver = () => {
    resizeObserverRef.current?.disconnect();
    resizeObserverRef.current = null;
  };

  const initializeCursor = useCallback((nextAnchorElement: HTMLElement, nextAnchorFrameElement: HTMLElement) => {
    anchorElementRef.current = nextAnchorElement;
    anchorFrameElementRef.current = nextAnchorFrameElement;
    runIdRef.current += 1;
    const runId = runIdRef.current;

    cleanupResizeObserver();
    clearBinding(true);

    const cursor = createCursor(nextAnchorElement);

    const onPause = () => setState("paused");
    const onPlay = () => setState("running");
    const onDestroy = () => {
      if (runIdRef.current === runId) {
        setState("idle");
      }
    };

    cursor.on("pause", onPause);
    cursor.on("play", onPlay);
    cursor.on("destroy", onDestroy);

    bindingRef.current = {
      cursor,
      anchorElement: nextAnchorElement,
      anchorFrameElement: nextAnchorFrameElement,
      activeScale: cursor.cursor.scale,
      onPause,
      onPlay,
      onDestroy,
    };

    syncCursorScale(cursor, nextAnchorFrameElement);

    if (typeof window !== "undefined" && window.requestAnimationFrame) {
      window.requestAnimationFrame(() => {
        if (bindingRef.current?.cursor === cursor) {
          syncCursorScale(cursor, nextAnchorFrameElement);
        }
      });
    }

    if (typeof ResizeObserver !== "undefined") {
      const observer = new ResizeObserver(() => {
        if (bindingRef.current?.cursor === cursor) {
          syncCursorScale(cursor, nextAnchorFrameElement);
        }
      });

      observer.observe(nextAnchorFrameElement);
      resizeObserverRef.current = observer;
    }

    setState("idle");
  }, [createCursor]);

  useEffect(() => {
    return () => {
      cleanupResizeObserver();
      clearBinding(true);
    };
  }, []);

  const syncBinding = useCallback(() => {
    const anchorElement = anchorElementRef.current;
    const anchorFrameElement = anchorFrameElementRef.current;

    if (!anchorElement || !anchorFrameElement) {
      return;
    }

    const currentBinding = bindingRef.current;
    if (
      currentBinding &&
      currentBinding.anchorElement === anchorElement &&
      currentBinding.anchorFrameElement === anchorFrameElement
    ) {
      syncCursorScale(currentBinding.cursor, anchorFrameElement);
      return;
    }

    initializeCursor(anchorElement, anchorFrameElement);
  }, [initializeCursor]);

  const setAnchorElement = useCallback((element: HTMLElement | null) => {
    if (!element) {
      anchorElementRef.current = null;
      cleanupResizeObserver();
      clearBinding(true);
      return;
    }

    anchorElementRef.current = element;
    syncBinding();
  }, [syncBinding]);

  const setAnchorFrameElement = useCallback((element: HTMLElement | null) => {
    if (!element) {
      anchorFrameElementRef.current = null;
      cleanupResizeObserver();
      clearBinding(true);
      return;
    }

    anchorFrameElementRef.current = element;
    syncBinding();
  }, [syncBinding]);

  const pause = () => {
    if (state !== "running") return;
    bindingRef.current?.cursor.pause();
  };

  const stop = () => {
    const binding = bindingRef.current;
    if (!binding) return;

    initializeCursor(binding.anchorElement, binding.anchorFrameElement);
  };

  const start = async () => {
    const binding = bindingRef.current;
    if (!binding) return;

    if (state === "running") return;

    if (state === "paused") {
      binding.cursor.play();
      return;
    }

    try {
      setState("running");
      restoreCursorScale(binding.cursor, binding.activeScale);
      buildSequence(binding.cursor, binding.anchorElement);

      await binding.cursor;

      if (isSameBinding(bindingRef.current, binding)) {
        initializeCursor(binding.anchorElement, binding.anchorFrameElement);
      }
    } catch (error) {
      if (isSameBinding(bindingRef.current, binding)) {
        clearBinding(true);
        setState("error");
        initializeCursor(binding.anchorElement, binding.anchorFrameElement);
      }

      onError?.(error);
    }
  };

  return {
    state,
    canStart: state !== "running",
    canPause: state === "running",
    canStop: state === "running" || state === "paused",
    start,
    pause,
    stop,
    setAnchorElement,
    setAnchorFrameElement,
  };
}
